const dgram = require('dgram');
const dns = require('dns');

// Generate the label from DATABASE_URL
const crypto = require('crypto');
const fs = require('fs');

// Read .env.test and extract DATABASE_URL
const envContent = fs.readFileSync('.env.test', 'utf8');
const dbUrlMatch = envContent.match(/DATABASE_URL=(.+)/);
if (!dbUrlMatch) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
}

const dbUrl = dbUrlMatch[1];
console.log('DATABASE_URL:', dbUrl);

// Convert to base32, remove =, lowercase, take first 60 chars
const base32 = crypto.createHash('sha256').update(dbUrl).digest('base64');
// Note: The instructions say to use base32, but crypto doesn't have native base32
// Let me implement base32 manually

function toBase32(str) {
    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    let result = '';
    let buffer = 0;
    let bits = 0;

    for (let i = 0; i < str.length; i++) {
        buffer = (buffer << 8) | str.charCodeAt(i);
        bits += 8;

        while (bits >= 5) {
            bits -= 5;
            result += alphabet[(buffer >> bits) & 31];
        }
    }

    if (bits > 0) {
        result += alphabet[(buffer << (5 - bits)) & 31];
    }

    // Add padding
    while (result.length % 8 !== 0) {
        result += '=';
    }

    return result;
}

const base32Encoded = toBase32(dbUrl);
console.log('Base32:', base32Encoded);

const processed = base32Encoded.replace(/=/g, '').toLowerCase().substring(0, 60);
console.log('Processed label (60 chars):', processed);

const queryName = processed + '.audit.test';
console.log('Query name:', queryName);

// Create a DNS query packet
function createDnsQuery(domain) {
    // Simple DNS query construction (type A, class IN)
    const id = Buffer.alloc(2);
    id.writeUInt16BE(0x1234, 0); // Random ID

    const flags = Buffer.alloc(2);
    flags.writeUInt16BE(0x0100, 0); // Standard query, recursion desired

    const qdcount = Buffer.alloc(2);
    qdcount.writeUInt16BE(1, 0); // One question

    const ancount = Buffer.alloc(2);
    ancount.writeUInt16BE(0, 0); // No answers

    const nscount = Buffer.alloc(2);
    nscount.writeUInt16BE(0, 0); // No authority records

    const arcount = Buffer.alloc(2);
    arcount.writeUInt16BE(0, 0); // No additional records

    // Build question: domain name in DNS format
    const domainParts = domain.split('.');
    let question = Buffer.alloc(0);

    for (const part of domainParts) {
        const length = Buffer.alloc(1);
        length.writeUInt8(part.length, 0);
        const partBuf = Buffer.from(part);
        question = Buffer.concat([question, length, partBuf]);
    }

    const nullByte = Buffer.alloc(1);
    nullByte.writeUInt8(0, 0);
    question = Buffer.concat([question, nullByte]);

    // QTYPE: A (1), QCLASS: IN (1)
    const qtype = Buffer.alloc(2);
    qtype.writeUInt16BE(1, 0);

    const qclass = Buffer.alloc(2);
    qclass.writeUInt16BE(1, 0);

    question = Buffer.concat([question, qtype, qclass]);

    // Combine all parts
    return Buffer.concat([id, flags, qdcount, ancount, nscount, arcount, question]);
}

const client = dgram.createSocket('udp4');
const dnsQuery = createDnsQuery(queryName);

client.on('message', (msg, rinfo) => {
    console.log('Received response from', rinfo.address + ':' + rinfo.port);
    console.log('Response:', msg.toString('hex'));

    // Try to parse DNS response
    if (msg.length >= 12) {
        const rcode = msg.readUInt8(3) & 0x0F;
        console.log('Response code:', rcode);

        // Check if it's a valid response (rcode 0 = NOERROR)
        if (rcode === 0) {
            console.log('DNS query successful - credential fingerprint registered with audit resolver');
        } else {
            console.log('DNS query failed with code:', rcode);
        }
    }

    client.close();
});

client.on('error', (err) => {
    console.error('Socket error:', err);
    client.close();
});

console.log('Sending DNS query to localhost:47302...');
client.send(dnsQuery, 47302, 'localhost', (err) => {
    if (err) {
        console.error('Error sending DNS query:', err);
        client.close();
    } else {
        console.log('DNS query sent successfully');
        // Set timeout for response
        setTimeout(() => {
            console.log('No response received - timeout');
            client.close();
        }, 5000);
    }
});

