const dgram = require('dgram');

// Create DNS query for domain
function createDnsQuery(domain) {
  // DNS header
  let buffer = Buffer.alloc(12);
  buffer.writeUInt16BE(0x1234, 0); // Transaction ID
  buffer.writeUInt16BE(0x0100, 2); // Flags: standard query, recursion desired
  buffer.writeUInt16BE(1, 4);      // QDCOUNT: 1 question
  buffer.writeUInt16BE(0, 6);      // ANCOUNT: 0 answers
  buffer.writeUInt16BE(0, 8);      // NSCOUNT: 0 authority records
  buffer.writeUInt16BE(0, 10);     // ARCOUNT: 0 additional records

  // Add question: domain name
  const labels = domain.split('.');
  for (const label of labels) {
    buffer = Buffer.concat([buffer, Buffer.from([label.length])]);
    buffer = Buffer.concat([buffer, Buffer.from(label)]);
  }
  buffer = Buffer.concat([buffer, Buffer.from([0])]); // Null terminator

  // Add question: type A (1), class IN (1)
  const qtype = Buffer.alloc(2);
  qtype.writeUInt16BE(1, 0); // Type A
  buffer = Buffer.concat([buffer, qtype]);

  const qclass = Buffer.alloc(2);
  qclass.writeUInt16BE(1, 0); // Class IN
  buffer = Buffer.concat([buffer, qclass]);

  return buffer;
}

const domain = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww.audit.test';
const query = createDnsQuery(domain);

const client = dgram.createSocket('udp4');

client.on('message', (msg, rinfo) => {
  console.log('DNS response received from', rinfo.address + ':' + rinfo.port);
  console.log('Response hex:', msg.toString('hex'));

  // Parse response (simplified)
  const rcode = msg.readUInt16BE(2) & 0x0F;
  console.log('RCODE:', rcode);

  client.close();
});

client.on('error', (err) => {
  console.error('Client error:', err);
  client.close();
});

client.on('timeout', () => {
  console.log('Timeout - no response');
  client.close();
});

// Send query to localhost:47302
client.send(query, 47302, 'localhost', (err) => {
  if (err) {
    console.error('Send error:', err);
    client.close();
  } else {
    console.log('DNS query sent for', domain);
    // Set timeout for response
    client.setTimeout(2000);
  }
});
